-- 20/10/2026 (Nolan, go « bloc 4 ») : questions « À trancher » au magasin (doublons, 200x50, contradictions de taille, versions). Admin uniquement.
create table if not exists public.atelier_questions (
  id text primary key,
  famille text not null check (famille in ('doublons','200x50','contradictions','variantes')),
  ordre int not null default 0,
  titre text not null,
  contexte text,
  regarder text,
  choix text[] not null default '{}',
  reponse text,
  note text,
  repondu_le timestamptz,
  repondu_par uuid,
  traitee boolean not null default false,
  created_at timestamptz not null default now()
);
alter table public.atelier_questions enable row level security;
drop policy if exists "admin gère les questions atelier" on public.atelier_questions;
create policy "admin gère les questions atelier" on public.atelier_questions for all
  using (public.has_role(auth.uid(), 'admin'::public.app_role))
  with check (public.has_role(auth.uid(), 'admin'::public.app_role));
on conflict (id) do nothing;
